        <div class="section-block application-inner"><div class="section-head"><p class="eyebrow">申请 · APPLICATION</p><h2>填写免修、免考申请表</h2><p>请如实填写并上传证明，带 <em>*</em> 为必填项。</p></div>
          <div class="application-grid"><form v-if="!application" class="application-form" @submit.prevent="submitApplication"><section class="form-card"><div class="form-card-title"><span>01</span><h3>基本信息</h3><b>必填</b></div><div class="field-grid"><label>姓名 <em>*</em><input v-model="form.name" placeholder="请输入真实姓名"></label><label>学号 <em>*</em><input v-model="form.studentNo" placeholder="请输入学号"></label><label>所在学院 <em>*</em><select v-model="form.college"><option value="">请选择学院</option><option>动物科学学院</option><option>农学院</option><option>林学院</option><option>草原与资源环境学院</option><option>计算机与信息工程学院</option><option>经济管理学院</option><option>其他</option></select></label><label>专业<input v-model="form.major" placeholder="请输入专业名称"></label><label>年级 <em>*</em><select v-model="form.grade"><option value="">请选择年级</option><option>2026 级</option><option>2025 级</option><option>2024 级</option><option>2023 级</option></select></label><label>联系电话 <em>*</em><input v-model="form.phone" placeholder="请输入手机号"></label><label class="wide">邮箱<input v-model="form.email" type="email" placeholder="name@example.edu.cn"></label></div></section>
            <section class="form-card"><div class="form-card-title"><span>02</span><h3>申请信息</h3></div><div class="form-stack"><fieldset><legend>申请课程 <em>*</em></legend><label class="choice"><input v-model="form.courses" type="checkbox" value="大学英语2">大学英语2</label><label class="choice"><input v-model="form.courses" type="checkbox" value="大学英语3">大学英语3</label></fieldset><fieldset><legend>申请方式 <em>*</em></legend><label class="choice"><input v-model="form.mode" type="radio" value="免修免考">免修免考</label><label class="choice"><input v-model="form.mode" type="radio" value="免修不免考">免修不免考</label><p class="field-hint">免修不免考：最终成绩按期末考试卷面成绩计入。</p></fieldset><div class="field-grid"><label>认证类型 <em>*</em><select v-model="form.certificate"><option value="">请选择认证类型</option><option>大学英语四级 CET-4</option><option>大学英语六级 CET-6</option><option>雅思 IELTS</option><option>托福 TOEFL</option></select></label><label>认证成绩 <em>*</em><input v-model="form.score" placeholder="如：497"></label></div><label v-if="needsExamDate">成绩获得日期 <em>*</em><input v-model="form.examDate" type="date"></label><label>申请理由<textarea v-model="form.reason" rows="4" placeholder="请简要说明已取得的语言成绩与申请免修、免考的理由……"></textarea></label></div></section>
            <section class="form-card"><div class="form-card-title"><span>03</span><h3>证明材料</h3></div><label class="upload-label">成绩单 / 证书扫描件 <em>*</em><input type="file" accept="image/*,.pdf" @change="selectFile"><span class="upload-box"><el-icon><UploadFilled /></el-icon><b>{{ proofName || '点击上传，或将文件拖拽到此区域' }}</b><small>雅思、托福成绩请提供获得时间 2 年内的证明</small></span></label><label class="commitment"><input v-model="form.committed" type="checkbox"><span>本人承诺以上信息与材料真实、准确、有效，如有虚假愿承担相应责任。 <em>*</em></span></label></section><div class="form-actions"><button type="button" class="draft-button">保存草稿</button><button type="submit" class="submit-button" :disabled="submitting">{{ submitting ? '提交中…' : '提交申请' }}</button></div></form>
            <section v-else class="form-card submitted-card"><div class="submitted-icon"><el-icon><DocumentChecked /></el-icon></div><div><p>我的申请状态</p><h3>{{ statusText }}</h3><span>申请提交于 {{ application.createdTime }}。<template v-if="application.reviewComment">审批意见：{{ application.reviewComment }}</template><template v-else>审核结果以系统通知为准。</template></span></div></section>
            <aside class="application-aside"><section><div class="aside-title"><el-icon><Clock /></el-icon><h3>申请须知</h3></div><ul><li>申请通过后不得中途变更。</li><li>未在规定时间提出申请者，须正常参加课程学习和考核。</li><li>申请材料视同课程考核资料，按教学档案存档要求管理。</li></ul></section><section><div class="aside-title"><h3>我的申请进度</h3><button type="button" @click="loadApplication">刷新</button></div><div class="progress-list"><div class="completed"><i>✓</i><p><b>已提交申请</b><small>{{ application ? application.createdTime : '提交申请后显示时间' }}</small></p></div><div :class="{ pending: application?.status === 'PENDING' }"><i>02</i><p><b>任课教师审批</b><small>{{ application?.status === 'PENDING' ? '等待审批中' : statusText }}</small></p></div><div><i>03</i><p><b>教务处备案</b><small>{{ application?.status === 'APPROVED' ? '待备案' : '未开始' }}</small></p></div></div></section></aside>
          </div>
          <el-alert v-if="errorMessage" class="submit-error" :title="errorMessage" type="error" :closable="false" show-icon />
        </div>
      </section>
    </main>
    <footer class="site-footer"><div><span class="brand-mark">农</span><b>内蒙古农业大学 · 大学英语免修、免考申请</b><p>依据《内蒙古农业大学关于大学英语课程免修、免考实施细则（试行）》（内农大教字〔2025〕18号）</p></div><span>由教务处、外国语学院负责解释</span></footer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { Bell, Clock, DocumentChecked, UploadFilled } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { getMyEnglishExemptionApplication, submitEnglishExemptionApplication } from '@/api/student'
import { uploadMedia } from '@/api/media'
import XyMascot from '@/components/ui/XyMascot.vue'

const flowItems = [{ title: '下载填写申请表', description: '登录学校教务处网站主页，下载并填写《大学英语免修免考申请表》。' }, { title: '所在学院审批', description: '将申请表提交学生所在学院，由学院完成审批。' }, { title: '任课教师审批', description: '由对应《大学英语》课程任课教师审批确认。' }, { title: '教务处备案', description: '经教务处审批备案后，免修、免考申请正式生效。' }]
const criteriaItems = [{ name: '大学英语四级', score: '≥ 497 分', description: '大学英语四级达到 497 分（含）以上。' }, { name: '大学英语六级', score: '≥ 425 分', description: '大学英语六级达到 425 分（含）以上。' }, { name: '雅思', score: '≥ 6.0 分', description: '雅思 6 分（含）以上，获得时间未超出 2 年。' }, { name: '托福', score: '≥ 68 分', description: '托福 68 分（含）以上，获得时间未超出 2 年。' }]
const cet4Scores = [['497–524 分', '80 分'], ['525–574 分', '85 分'], ['575–624 分', '90 分'], ['625–674 分', '95 分'], ['≥ 675 分', '100 分']]
const cet6Scores = [['425–459 分', '80 分'], ['460–499 分', '85 分'], ['500–549 分', '90 分'], ['550–599 分', '95 分'], ['≥ 600 分', '100 分']]
const ieltsScores = [['6.0 分', '80 分'], ['6.5 分', '85 分'], ['7.0 分', '90 分'], ['7.5 分', '95 分'], ['≥ 8.0 分', '100 分']]
const toeflScores = [['68–79 分', '80 分'], ['80–91 分', '85 分'], ['92–102 分', '90 分'], ['103–112 分', '95 分'], ['≥ 113 分', '100 分']]
const application = ref(null)
const submitting = ref(false)
const errorMessage = ref('')
const proofName = ref('')
const proofFile = ref(null)
const form = reactive({ name: '', studentNo: '', college: '', major: '', grade: '', phone: '', email: '', courses: [], mode: '', certificate: '', score: '', examDate: '', reason: '', committed: false })
const statusText = computed(() => ({ PENDING: '等待审核', APPROVED: '审核通过', REJECTED: '审核未通过' }[application.value?.status] || application.value?.status || '已提交'))
const examTypeMap = { '大学英语四级 CET-4': 'CET4', '大学英语六级 CET-6': 'CET6', '雅思 IELTS': 'IELTS', '托福 TOEFL': 'TOEFL' }
const needsExamDate = computed(() => ['雅思 IELTS', '托福 TOEFL'].includes(form.certificate))
function selectFile(event) {
  proofFile.value = event.target.files?.[0] || null
  proofName.value = proofFile.value?.name || ''
}
async function loadApplication() {
  const response = await getMyEnglishExemptionApplication()
  application.value = response?.data || null
}
function makeRemark() {
  return ['姓名：' + form.name, '学号：' + form.studentNo, '学院：' + form.college, '专业：' + (form.major || '未填写'), '年级：' + form.grade, '电话：' + form.phone, '邮箱：' + (form.email || '未填写'), '申请理由：' + (form.reason || '未填写')].join('\n')
}
async function submitApplication() {
  errorMessage.value = ''
  if (!form.name || !form.studentNo || !form.college || !form.grade || !form.phone || !form.courses.length || !form.mode || !form.certificate || !form.score || !proofFile.value || !form.committed || (needsExamDate.value && !form.examDate)) {
    ElMessage.warning('请完成所有必填信息、上传证明并确认承诺')
    return
  }
  submitting.value = true
  try {
    const proofExtension = (proofFile.value.name.split('.').pop() || '').toLowerCase()
    const mediaType = proofExtension === 'pdf' || proofFile.value.type === 'application/pdf' ? 'DOCUMENT' : 'IMAGE'
    const uploadResponse = await uploadMedia(proofFile.value, mediaType)
    const uploaded = uploadResponse?.data
    if (!uploaded?.url && !uploaded?.mediaId) throw new Error(uploadResponse?.message || '证明材料上传失败')
    const certificateUrl = uploaded.url || ('/api/media/' + uploaded.mediaId + '/download')
    const response = await submitEnglishExemptionApplication({
      courseName: form.courses.join('、'),
      applyType: form.mode === '免修免考' ? 'EXEMPT_FULL' : 'EXEMPT_WITH_EXAM',
      examType: examTypeMap[form.certificate],
      examScore: form.score,
      examDate: needsExamDate.value ? form.examDate : null,
      certificateUrl,
      studentRemark: makeRemark()
    })
    application.value = response.data
    ElMessage.success('申请已提交，任课教师将收到审核通知')
  } catch (error) {
    errorMessage.value = error?.response?.data?.message || error?.message || '申请提交失败，请稍后重试。'
  } finally {
    submitting.value = false
  }
}
onMounted(() => loadApplication().catch(() => {}))
</script>

