.site-header { position:sticky; top:0; z-index:10; border-bottom:1px solid rgba(216,241,226,.7); background:rgba(255,255,255,.9); backdrop-filter:blur(12px); }.header-inner,.hero-inner,.section-block,.site-footer { width:min(1120px, calc(100% - 40px)); margin:0 auto; }.header-inner { display:flex; height:64px; align-items:center; justify-content:space-between; gap:20px; }.brand { display:flex; align-items:center; gap:10px; color:var(--ink-900); text-decoration:none; }.brand-mark { display:grid; width:36px; height:36px; place-items:center; border-radius:12px; background:linear-gradient(135deg,var(--leaf-500),var(--leaf-700)); color:#fff; font-family:Georgia,serif; font-size:18px; font-weight:700; }.brand-title { font-size:15px; font-weight:700; }.school-name,.criterion-tag { border-radius:999px; background:var(--leaf-50); color:var(--leaf-600); font-size:12px; font-weight:600; }.school-name { padding:4px 10px; }.desktop-nav { display:flex; gap:30px; }.desktop-nav a { color:var(--ink-500); font-size:14px; font-weight:600; text-decoration:none; }.desktop-nav a:hover,.desktop-nav .active { color:var(--leaf-600); }.notification-button { position:relative; display:grid; width:36px; height:36px; place-items:center; border:0; border-radius:50%; background:transparent; color:var(--ink-500); font-size:18px; cursor:pointer; }.notification-button:hover { background:var(--leaf-50); color:var(--leaf-600); }.notification-button span { position:absolute; top:8px; right:8px; width:7px; height:7px; border:2px solid #fff; border-radius:50%; background:#ef4444; }
