ce-items:center; border:1px solid rgba(255,255,255,.75); border-radius:34px; background:rgba(255,255,255,.65); box-shadow:0 20px 35px rgba(18,160,90,.12); }.float-card { position:absolute; z-index:2; display:grid; gap:3px; padding:11px 14px; border:1px solid var(--leaf-100); border-radius:14px; background:#fff; box-shadow:0 10px 20px rgba(18,160,90,.1); }.float-card small { color:var(--ink-400); font-size:11px; }.float-card strong { color:var(--leaf-600); font-family:"Noto Serif SC",serif; font-size:15px; }.card-left { top:44px; left:-10px; }.card-right { right:-4px; bottom:26px; }
